            totalSent += amount;
        }
        for (uint256 i = 0; i < numCallsB; i++) {
            vm.prank(bob);
            c.Put{value: amount}(lockTime);
            totalSent += amount;
        }

        uint256 totalStored = c.Acc(alice).balance + c.Acc(bob).balance;
        uint256 totalCollected = totalSent - address(c).balance;

        assertEq(totalStored, totalSent + totalCollected);
    }
}

